"use client";

import React, {
  createContext,
  useContext,
  useState,
  useEffect,
  ReactNode,
  useMemo,
  useCallback,
} from "react";
import { Auth, User, signInWithEmailAndPassword, signOut } from "firebase/auth";
import { useFirebaseInit } from "./useFirebaseInit";

export interface AuthContextType {
  user: User | null;
  auth: Auth | null;
  userId: string | null;
  isAuthenticated: boolean; // 匿名ユーザーは認証済みにしない
  isLoading: boolean;
  isLoggingOut: boolean;
  login: (credentials: { email: string; password: string }) => Promise<void>;
  logout: (redirectPath?: string) => Promise<void>;
}

const AuthContext = createContext<AuthContextType | null>(null);

export function AuthProvider({ children }: { children: ReactNode }) {
  const { auth, userId, isReady } = useFirebaseInit();
  const [user, setUser] = useState<User | null>(null);
  const [isLoggingOut, setIsLoggingOut] = useState(false);

  // Firebase Auth リスナー
  useEffect(() => {
    if (!auth) return;

    const unsubscribe = auth.onAuthStateChanged((currentUser) => {
      setUser(currentUser);
    });

    return () => unsubscribe();
  }, [auth]);

  // 匿名ユーザーはログイン済みとみなさない
  const isAuthenticated = useMemo(() => !!user && !user.isAnonymous, [user]);

  const isLoading = useMemo(() => !isReady, [isReady]);

  const login = useCallback(
    async ({ email, password }: { email: string; password: string }) => {
      if (!auth) throw new Error("Auth service is unavailable.");
      await signInWithEmailAndPassword(auth, email, password);
    },
    [auth]
  );

  const logout = useCallback(
    async (redirectPath = "/") => {
      if (!auth) return;
      setIsLoggingOut(true);
      try {
        await signOut(auth);
        console.log(`Logout successful. Redirect to: ${redirectPath}`);
      } catch (err) {
        console.error("Logout Error:", err);
      } finally {
        setIsLoggingOut(false);
      }
    },
    [auth]
  );

  return (
    <AuthContext.Provider
      value={{
        user,
        auth,
        userId,
        isAuthenticated,
        isLoading,
        isLoggingOut,
        login,
        logout,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (!context) throw new Error("useAuth must be used within AuthProvider");
  return context;
};
